272	
273		host, _ := cfg.DefaultHost()
274	
275		if opts.Interactive {
276			opts.Name, opts.Description, opts.Visibility, err = interactiveRepoInfo(opts.Prompter, "")
277			if err != nil {
278				return err
279			}
280			opts.AddReadme, err = opts.Prompter.Confirm("Would you like to add a README file?", false)
281			if err != nil {
282				return err
283			}
284			opts.GitIgnoreTemplate, err = interactiveGitIgnore(httpClient, host, opts.Prompter)
285			if err != nil {
286				return err
287			}
288			opts.LicenseTemplate, err = interactiveLicense(httpClient, host, opts.Prompter)
289			if err != nil {
290				return err
291			}
292	
293			targetRepo := shared.NormalizeRepoName(opts.Name)
294			if idx := strings.IndexRune(targetRepo, '/'); idx > 0 {
295				targetRepo = targetRepo[0:idx+1] + shared.NormalizeRepoName(targetRepo[idx+1:])
296			}
297			confirmed, err := opts.Prompter.Confirm(fmt.Sprintf(`This will create "%s" as a %s repository on GitHub. Continue?`, targetRepo, strings.ToLower(opts.Visibility)), true)
298			if err != nil {
299				return err
300			} else if !confirmed {
301				return cmdutil.CancelError
302			}
303		}
304	
305		if strings.Contains(opts.Name, "/") {
306			var err error
307			repoToCreate, err = ghrepo.FromFullName(opts.Name)
308			if err != nil {
309				return fmt.Errorf("argument error: %w", err)
310			}
311		} else {
312			repoToCreate = ghrepo.NewWithHost("", opts.Name, host)
313		}
314	
315		input := repoCreateInput{
316			Name:               repoToCreate.RepoName(),
317			Visibility:         opts.Visibility,
318			OwnerLogin:         repoToCreate.RepoOwner(),
319			TeamSlug:           opts.Team,
320			Description:        opts.Description,
321			HomepageURL:        opts.Homepage,
322			HasIssuesEnabled:   !opts.DisableIssues,
323			HasWikiEnabled:     !opts.DisableWiki,
324			GitIgnoreTemplate:  opts.GitIgnoreTemplate,
325			LicenseTemplate:    opts.LicenseTemplate,
326			IncludeAllBranches: opts.IncludeAllBranches,
327			InitReadme:         opts.AddReadme,
328		}
329	
330		var templateRepoMainBranch string
331		if opts.Template != "" {
332			var templateRepo ghrepo.Interface
333			apiClient := api.NewClientFromHTTP(httpClient)
334	
335			templateRepoName := opts.Template
336			if !strings.Contains(templateRepoName, "/") {
337				currentUser, err := api.CurrentLoginName(apiClient, host)
338				if err != nil {
339					return err
340				}
341				templateRepoName = currentUser + "/" + templateRepoName
342			}
343			templateRepo, err = ghrepo.FromFullName(templateRepoName)
344			if err != nil {
345				return fmt.Errorf("argument error: %w", err)
346			}
347	
348			repo, err := api.GitHubRepo(apiClient, templateRepo)
349			if err != nil {
350				return err
351			}
352	
353			input.TemplateRepositoryID = repo.ID
354			templateRepoMainBranch = repo.DefaultBranchRef.Name
355		}
356	
357		repo, err := repoCreate(httpClient, repoToCreate.RepoHost(), input)
358		if err != nil {
359			return err
360		}
361	
362		cs := opts.IO.ColorScheme()
363		isTTY := opts.IO.IsStdoutTTY()
364		if isTTY {
365			fmt.Fprintf(opts.IO.Out,
366				"%s Created repository %s on GitHub\n",
367				cs.SuccessIconWithColor(cs.Green),
368				ghrepo.FullName(repo))
369		} else {
370			fmt.Fprintln(opts.IO.Out, repo.URL)
371		}
372	
373		if opts.Interactive {
374			var err error
375			opts.Clone, err = opts.Prompter.Confirm("Clone the new repository locally?", true)
376			if err != nil {
377				return err
378			}
379		}
380	
381		if opts.Clone {
382			protocol, err := cfg.GetOrDefault(repo.RepoHost(), "git_protocol")
383			if err != nil {
384				return err
385			}
386	
387			remoteURL := ghrepo.FormatRemoteURL(repo, protocol)
388	
389			if opts.LicenseTemplate == "" && opts.GitIgnoreTemplate == "" {
390				// cloning empty repository or template
391				checkoutBranch := ""
392				if opts.Template != "" {
393					// use the template's default branch
394					checkoutBranch = templateRepoMainBranch
395				}
396				if err := localInit(opts.GitClient, remoteURL, repo.RepoName(), checkoutBranch); err != nil {
397					return err
398				}
399			} else if _, err := opts.GitClient.Clone(context.Background(), remoteURL, []string{}); err != nil {
400				return err
401			}
402		}
403	
404		return nil
405	}
406	
407	// create repo on remote host from existing local repo
408	func createFromLocal(opts *CreateOptions) error {
409		httpClient, err := opts.HttpClient()
410		if err != nil {
411			return err
412		}
413	
414		cs := opts.IO.ColorScheme()
415		isTTY := opts.IO.IsStdoutTTY()
416		stdout := opts.IO.Out
417	
418		cfg, err := opts.Config()
419		if err != nil {
420			return err
421		}
422		host, _ := cfg.DefaultHost()
423	
424		if opts.Interactive {
425			var err error
426			opts.Source, err = opts.Prompter.Input("Path to local repository", ".")
427			if err != nil {
428				return err
429			}
430		}
431	
432		repoPath := opts.Source
433		opts.GitClient.RepoDir = repoPath
434	
435		var baseRemote string
436		if opts.Remote == "" {
437			baseRemote = "origin"
438		} else {
439			baseRemote = opts.Remote
440		}
441	
442		absPath, err := filepath.Abs(repoPath)
443		if err != nil {
444			return err
445		}
446	
447		isRepo, err := isLocalRepo(opts.GitClient)
448		if err != nil {
449			return err
450		}
451		if !isRepo {
452			if repoPath == "." {
453				return fmt.Errorf("current directory is not a git repository. Run `git init` to initialize it")
454			}
455			return fmt.Errorf("%s is not a git repository. Run `git -C \"%s\" init` to initialize it", absPath, repoPath)
456		}
457	
458		committed, err := hasCommits(opts.GitClient)
459		if err != nil {
460			return err
461		}
462		if opts.Push {
463			// fail immediately if trying to push with no commits
464			if !committed {
465				return fmt.Errorf("`--push` enabled but no commits found in %s", absPath)
466			}
467		}
468	
469		if opts.Interactive {
470			opts.Name, opts.Description, opts.Visibility, err = interactiveRepoInfo(opts.Prompter, filepath.Base(absPath))
471			if err != nil {
472				return err
473			}
474		}
475	
476		var repoToCreate ghrepo.Interface
477	
478		// repo name will be currdir name or specified
479		if opts.Name == "" {
480			repoToCreate = ghrepo.NewWithHost("", filepath.Base(absPath), host)
481		} else if strings.Contains(opts.Name, "/") {
482			var err error
483			repoToCreate, err = ghrepo.FromFullName(opts.Name)
484			if err != nil {
485				return fmt.Errorf("argument error: %w", err)
486			}
487		} else {
488			repoToCreate = ghrepo.NewWithHost("", opts.Name, host)
489		}
490	
491		input := repoCreateInput{
492			Name:              repoToCreate.RepoName(),
493			Visibility:        opts.Visibility,
494			OwnerLogin:        repoToCreate.RepoOwner(),
495			TeamSlug:          opts.Team,
496			Description:       opts.Description,
497			HomepageURL:       opts.Homepage,
498			HasIssuesEnabled:  !opts.DisableIssues,
499			HasWikiEnabled:    !opts.DisableWiki,
500			GitIgnoreTemplate: opts.GitIgnoreTemplate,
501			LicenseTemplate:   opts.LicenseTemplate,
502		}
503	
504		repo, err := repoCreate(httpClient, repoToCreate.RepoHost(), input)
505		if err != nil {
506			return err
507		}
508	
509		if isTTY {
510			fmt.Fprintf(stdout,
511				"%s Created repository %s on GitHub\n",
512				cs.SuccessIconWithColor(cs.Green),
513				ghrepo.FullName(repo))
514		} else {
515			fmt.Fprintln(stdout, repo.URL)
516		}
517	
518		protocol, err := cfg.GetOrDefault(repo.RepoHost(), "git_protocol")
519		if err != nil {
520			return err
521		}
522	
523		remoteURL := ghrepo.FormatRemoteURL(repo, protocol)
524	
525		if opts.Interactive {
526			addRemote, err := opts.Prompter.Confirm("Add a remote?", true)
527			if err != nil {
528				return err
529			}
530			if !addRemote {
531				return nil
532			}
533	
534			baseRemote, err = opts.Prompter.Input("What should the new remote be called?", "origin")
535			if err != nil {
536				return err
537			}
538		}
539	
540		if err := sourceInit(opts.GitClient, opts.IO, remoteURL, baseRemote); err != nil {
541			return err
542		}
543	
544		// don't prompt for push if there are no commits
545		if opts.Interactive && committed {
546			var err error
547			opts.Push, err = opts.Prompter.Confirm(fmt.Sprintf("Would you like to push commits from the current branch to %q?", baseRemote), true)
548			if err != nil {
549				return err
550			}
551		}
552	
553		if opts.Push {
554			err := opts.GitClient.Push(context.Background(), baseRemote, "HEAD")
555			if err != nil {
556				return err
557			}
558			if isTTY {
559				fmt.Fprintf(stdout, "%s Pushed commits to %s\n", cs.SuccessIcon(), remoteURL)
560			}
561		}
562		return nil
563	}
564	
565	func sourceInit(gitClient *git.Client, io *iostreams.IOStreams, remoteURL, baseRemote string) error {
566		cs := io.ColorScheme()
567		remoteAdd, err := gitClient.Command(context.Background(), "remote", "add", baseRemote, remoteURL)
568		if err != nil {
569			return err
570		}
571		_, err = remoteAdd.Output()
572		if err != nil {
573			return fmt.Errorf("%s Unable to add remote %q", cs.FailureIcon(), baseRemote)
574		}
575		if io.IsStdoutTTY() {
576			fmt.Fprintf(io.Out, "%s Added remote %s\n", cs.SuccessIcon(), remoteURL)
577		}
578		return nil
579	}
580	
581	// check if local repository has committed changes
582	func hasCommits(gitClient *git.Client) (bool, error) {
583		hasCommitsCmd, err := gitClient.Command(context.Background(), "rev-parse", "HEAD")
584		if err != nil {
585			return false, err
586		}
587		_, err = hasCommitsCmd.Output()
588		if err == nil {
589			return true, nil
590		}
591	
592		var execError *exec.ExitError
593		if errors.As(err, &execError) {
594			exitCode := int(execError.ExitCode())
595			if exitCode == 128 {
596				return false, nil
597			}
598			return false, err
599		}
600		return false, nil
601	}
602	
603	// check if path is the top level directory of a git repo
604	func isLocalRepo(gitClient *git.Client) (bool, error) {
605		projectDir, projectDirErr := gitClient.GitDir(context.Background())
606		if projectDirErr != nil {
607			var execError *exec.ExitError
608			if errors.As(projectDirErr, &execError) {
609				if exitCode := int(execError.ExitCode()); exitCode == 128 {
610					return false, nil
611				}
612				return false, projectDirErr
613			}
614		}
615		if projectDir != ".git" {
616			return false, nil
617		}
618		return true, nil
619	}
620	
621	// clone the checkout branch to specified path
622	func localInit(gitClient *git.Client, remoteURL, path, checkoutBranch string) error {
623		ctx := context.Background()
624		gitInit, err := gitClient.Command(ctx, "init", path)
625		if err != nil {
626			return err
627		}
628		_, err = gitInit.Output()
629		if err != nil {
630			return err
631		}
632	
633		// Clone the client so we do not modify the original client's RepoDir.
634		gc := cloneGitClient(gitClient)
635		gc.RepoDir = path
636	
637		gitRemoteAdd, err := gc.Command(ctx, "remote", "add", "origin", remoteURL)
638		if err != nil {
639			return err
640		}
641		_, err = gitRemoteAdd.Output()
642		if err != nil {
643			return err
644		}
645	
646		if checkoutBranch == "" {
647			return nil
648		}
649	
650		refspec := fmt.Sprintf("+refs/heads/%[1]s:refs/remotes/origin/%[1]s", checkoutBranch)
651		err = gc.Fetch(ctx, "origin", refspec)
652		if err != nil {
653			return err
654		}
655	
656		return gc.CheckoutBranch(ctx, checkoutBranch)
657	}
658	
659	func interactiveGitIgnore(client *http.Client, hostname string, prompter iprompter) (string, error) {
660		confirmed, err := prompter.Confirm("Would you like to add a .gitignore?", false)
661		if err != nil {
662			return "", err
663		} else if !confirmed {
664			return "", nil
665		}
666	
667		templates, err := listGitIgnoreTemplates(client, hostname)
668		if err != nil {
669			return "", err
670		}
671		selected, err := prompter.Select("Choose a .gitignore template", "", templates)
672		if err != nil {
673			return "", err
674		}
675		return templates[selected], nil
676	}
677	
678	func interactiveLicense(client *http.Client, hostname string, prompter iprompter) (string, error) {
679		confirmed, err := prompter.Confirm("Would you like to add a license?", false)
680		if err != nil {
681			return "", err
682		} else if !confirmed {
683			return "", nil
684		}
685	
686		licenses, err := listLicenseTemplates(client, hostname)
687		if err != nil {
688			return "", err
689		}
690		licenseNames := make([]string, 0, len(licenses))
691		for _, license := range licenses {
692			licenseNames = append(licenseNames, license.Name)
693		}
694		selected, err := prompter.Select("Choose a license", "", licenseNames)
695		if err != nil {
696			return "", err
697		}
698		return licenses[selected].Key, nil
699	}
700	
701	// name, description, and visibility
702	func interactiveRepoInfo(prompter iprompter, defaultName string) (string, string, string, error) {
703		name, err := prompter.Input("Repository name", defaultName)
704		if err != nil {
705			return "", "", "", err
706		}
707	
708		description, err := prompter.Input("Description", defaultName)
709		if err != nil {
710			return "", "", "", err
711		}
712	
713		visibilityOptions := []string{"Public", "Private", "Internal"}
714		selected, err := prompter.Select("Visibility", "Public", visibilityOptions)
715		if err != nil {
716			return "", "", "", err
717		}
718	
719		return name, description, strings.ToUpper(visibilityOptions[selected]), nil
720	}
721	
722	func cloneGitClient(c *git.Client) *git.Client {
723		return &git.Client{
724			GhPath:  c.GhPath,
725			RepoDir: c.RepoDir,
726			GitPath: c.GitPath,
727			Stderr:  c.Stderr,
728			Stdin:   c.Stdin,
729			Stdout:  c.Stdout,
730		}
731	}
